import {feature,L,S} from './feature-core.mjs';

export const surprisingFeatures=[
feature({id:'tardigrades-space',category:'life',rubrics:['facts'],read:9,tags:['biologija','svemir'],
  hero:['tardigrade-portrait.jpg',L('Mikroskopska fotografija tardigrade.','Mikroskopska fotografija počasnika.','Microscope photograph of a tardigrade.'),L('Tardigrada, sićušna životinja koja u određenom stanju podnosi ekstremne uslove.','Počasnik, drobna žival, ki v določenem stanju prenese skrajne razmere.','A tardigrade, a tiny animal that tolerates extremes in a particular state.')],
  images:[['tardigrade-sem.png',L('Elektronski mikroskopski snimak tardigrade.','Elektronski mikroskopski posnetek počasnika.','Scanning electron image of a tardigrade.'),L('Elektronski mikroskop otkriva detalje građe nevidljive golim okom.','Elektronski mikroskop razkrije podrobnosti, nevidne s prostim očesom.','Electron microscopy reveals structures too small for the unaided eye.')],['tardigrade-eggs.jpg',L('Jaja tardigrade u odbačenoj košuljici.','Jajčeca počasnika v odvrženi kožici.','Tardigrade eggs in a shed cuticle.'),L('Tardigrade su stvarne životinje sa životnim ciklusom, ne neuništive „svemirske mašine”.','Počasniki so živali z življenjskim ciklom, ne neuničljivi »vesoljski stroji«.','Tardigrades are animals with life cycles, not indestructible “space machines”.')]],
  source:[['ESA — TARDIS experiment','https://www.esa.int/Science_Exploration/Human_and_Robotic_Exploration/Research/Tiny_animals_survive_exposure_to_space'],['Current Biology — research report','https://doi.org/10.1016/j.cub.2008.06.048']],
  translations:{
    sr:{slug:'tardigrade-prezivele-otvoreni-svemir',title:'Tardigrade su preživele otvoreni svemir — ali nisu neuništive',lead:'Ogled iz 2007. pokazao je izuzetnu otpornost „vodenih medvedića”, uz važnu razliku između preživljavanja i normalnog života.',remember:'Tardigrade su mikroskopske životinje koje mogu da pređu u stanje veoma usporenog metabolizma pri isušivanju. U eksperimentu Foton-M3 deo jedinki preživeo je oko 12 dana izloženosti svemirskim uslovima. Nisu sve preživele, naročito kada je uz vakuum delovalo i jako UV zračenje. Eksperiment ne pokazuje da mogu aktivno živeti ili se razmnožavati na bilo kojoj planeti.',term:'Kriptobioza — stanje u kome se životne aktivnosti organizma toliko uspore da postaju teško merljive.',sections:S([
      ['Životinja veličine zrnca','Tardigrade, poznate kao vodeni medvedići, imaju osam kratkih nogu i žive u tankom filmu vode oko mahovina, lišajeva, zemljišta ili u slatkoj i slanoj vodi. Većina je kraća od milimetra. Njihova neobična otpornost često se prikazuje kao supermoć, ali aktivna tardigrada nije neosetljiva na sve uslove. Da bi preživela isušivanje, neke vrste polako gube vodu i skupljaju se u takozvani tun. U tom stanju metabolizam se izuzetno usporava.','Zaštita nije jedna magična supstanca. U zavisnosti od vrste, važni su posebni proteini, stabilizacija ćelijskih struktura, kontrola oštećenja i sposobnost popravke kada se voda vrati. Različite vrste se razlikuju; rezultat za jednu vrstu ne može se automatski pripisati svim tardigradama. Zato istraživači mere i uslove pripreme, dužinu izlaganja i uspeh oporavka.'],
      ['Dvanaest dana na spoljašnjosti letelice','Švedski i nemački istraživači pripremili su eksperiment TARDIS na misiji Foton-M3. Oko 3.000 tardigrada poslato je u orbitu 2007. godine, a deo uzoraka bio je izložen uslovima otvorenog svemira približno dvanaest dana. Istraživači su odvojeno ispitivali uticaj vakuuma i kombinacije vakuuma sa Sunčevim zračenjem. Po povratku su životinje ponovo hidratizovali i pratili koje su se oporavile.','Ishod je bio zapanjujući: određeni broj jedinki preživeo je vakuum, a neke i dodatno zračenje. Ali uspeh nije bio stopostotan. Jako ultraljubičasto zračenje znatno je smanjivalo preživljavanje, a preživeti ne znači nužno da je svaka jedinka ostala potpuno zdrava ili se normalno razmnožavala. Naučni naslov zato mora da kaže „deo tardigrada”, a ne „svaka tardigrada uvek”.'],
      ['Šta je vakuum, a šta zračenje?','Vakuum znači veoma nizak pritisak i neposrednu opasnost da voda ispari iz tkiva. Životinja već isušena i u tun-stanju ima drugačiju polaznu tačku od aktivne životinje pune vode. Svemir donosi i UV svetlost i druge vrste jonizujućeg zračenja, velike temperaturne razlike i mikrogravitaciju. Svaki faktor deluje na drugačiji način; kombinacija može biti teža od pojedinačnog uticaja.','Laboratorijski ogled je zato bolje razumeti kao niz poređenja nego kao jedno pitanje „može li živeti u svemiru”. Naučnici kontrolišu koji uzorci dobijaju koji uslov, a zatim porede preživljavanje i oporavak. Nije isto biti izložen 12 dana u orbiti i naseliti suvu površinu Marsa tokom generacija. Oba scenarija se u popularnim tekstovima često mešaju.'],
      ['Zašto je rezultat važan?','Ako razumemo kako ćelije podnose sušenje i kako popravljaju oštećeni DNK, možemo bolje proučavati granice života. Takva istraživanja mogu nadahnuti metode čuvanja biološkog materijala, ali konkretna medicinska primena zahteva mnogo dodatnih koraka. Eksperiment je važan i za astrobiologiju: pokazuje da kratko preživljavanje u svemiru nije potpuno nemoguće za složenu životinju.','Ipak, to nije dokaz da život putuje između planeta. Za takvu tvrdnju morali bismo razmotriti izbacivanje sa planete, dugo putovanje, zaštitu od zračenja, ulazak u atmosferu, uspešan oporavak i razmnožavanje. Jedan uspešan korak ne dokazuje ceo niz. Upravo ta razlika između fascinantnog merenja i prevelikog zaključka čini priču naučno zanimljivom.'],
      ['Šta bismo još ispitali?','Naredni eksperimenti mogu porediti vrste, dužinu izlaganja, brzinu isušivanja i vrstu zračenja. Važno je meriti ne samo da li se jedinka pomera posle povratka, već i njenu dugoročnu fiziologiju, potomstvo i oštećenja ćelija. Kontrolne grupe ostaju na Zemlji u istim uslovima osim onog koji želimo testirati. Tako se razlikuje efekat leta od efekta rukovanja uzorkom.','Tardigrade nas podsećaju da otpornost nije apsolutna osobina poput „neuništivosti”. Ona je sposobnost pod određenim uslovima i sa granicama koje možemo izmeriti. To je mnogo korisnije, i zapravo neverovatnije, od mita o životinji koja može sve.']
    ])},
    sl:{slug:'pocasniki-preziveli-odprto-vesolje',title:'Počasniki so preživeli odprto vesolje — niso pa neuničljivi',lead:'Poskus leta 2007 je pokazal izjemno odpornost drobnih živali in razliko med preživetjem ter običajnim življenjem.',remember:'Počasniki lahko ob izsušitvi preidejo v stanje zelo upočasnjene presnove. V poskusu Foton-M3 je del živali preživel približno 12 dni izpostavljenosti vesolju. Vse niso preživele, posebno kadar se je vakuumu pridružilo močno UV-sevanje. Poskus ne dokazuje, da lahko dejavno živijo in se razmnožujejo na katerem koli planetu.',term:'Kriptobioza — stanje, v katerem so življenjski procesi organizma izredno upočasnjeni.',sections:S([
      ['Drobna žival','Počasniki imajo osem kratkih nog in živijo v tanki plasti vode na mahu, lišajih in v prsti ali vodnem okolju. Večina meri manj kot milimeter. Ob izsušitvi se nekatere vrste skrčijo v posebno stanje, imenovano tun, ter zelo upočasnijo presnovo. Dejavni počasnik ni odporen na vse. Različne vrste uporabljajo različne zaščitne beljakovine in mehanizme obnove, zato izida za ene ne smemo pripisati vsem.'],
      ['Dvanajst dni v orbiti','Švedski in nemški raziskovalci so leta 2007 poslali približno 3000 počasnikov na misijo Foton-M3. Del vzorcev je bil približno 12 dni izpostavljen razmeram zunaj kapsule. Ločili so vpliv vakuuma od dodatnega Sončevega sevanja, po vrnitvi pa živali ponovno navlažili. Nekatere so preživele, vendar ne vse. Močno ultravijolično sevanje je preživetje občutno zmanjšalo.'],
      ['Različne nevarnosti','Vakuum pomeni zelo nizek tlak, ki je nevaren za vodo v tkivih. Že izsušena žival ima drugačen izhodiščni položaj kot dejavna žival. Vesolje prinaša tudi UV- in ionizirajoče sevanje ter temperaturne skrajnosti. Raziskovalci morajo zato primerjati ločene skupine z natančno nadzorovanimi pogoji. Kratko preživetje ni enako dolgotrajnemu življenju na Marsu.'],
      ['Zakaj je to pomembno?','Razumevanje sušenja celic in popravljanja poškodovane DNK pomaga raziskovati meje življenja. Poskus je zanimiv tudi za astrobiologijo, vendar sam ne dokazuje prenosa življenja med planeti. Tak prenos bi moral vključevati izstrelitev, dolgo pot, prihod in uspešno razmnoževanje. Preživetje ene stopnje še ne potrdi vseh drugih.'],
      ['Kaj sledi','Prihodnje raziskave lahko primerjajo vrste, trajanje, sevanje in dolgoročno zdravje preživelih. Pomembno je preveriti tudi potomstvo ter uporabiti kontrolne skupine na Zemlji. Preveriti je treba, ali se živali po vrnitvi lahko normalno prehranjujejo, razvijajo in razmnožujejo. Odpornost ima merljive meje; beseda »neuničljiv« jih skrije. Resnični dosežek teh živali je zanimivejši od poenostavljenega mita.']
    ])},
    en:{slug:'tardigrades-survived-open-space',title:'Tardigrades survived open space — but they are not indestructible',lead:'A 2007 experiment showed extraordinary resilience and the difference between surviving and thriving.',remember:'Tardigrades can enter a state of extremely reduced metabolism when they dry out. Some survived about 12 days exposed to space during the Foton-M3 experiment. Not all survived, especially when strong ultraviolet light was added to vacuum. The finding does not show that they can actively live and reproduce on any planet.',term:'Cryptobiosis — a state in which an organism’s life processes slow to levels difficult to measure.',sections:S([
      ['A very small animal','Tardigrades have eight stubby legs and live in thin films of water around moss, lichens and soil or in aquatic habitats. Most are shorter than a millimetre. Some species dry into a compact “tun” state with extremely slow metabolism. An active tardigrade is not resistant to everything. Protective proteins and repair mechanisms differ between species, so a result for one cannot automatically be extended to all.'],
      ['Twelve days in orbit','In 2007 Swedish and German researchers sent roughly 3,000 tardigrades on the Foton-M3 mission. Some samples faced the conditions outside the capsule for about twelve days. Researchers separated the effects of vacuum from vacuum plus sunlight and rehydrated the animals after return. Some survived, but far from all. Strong ultraviolet exposure substantially reduced survival.'],
      ['Different hazards','Vacuum threatens the water in animal tissues. An already dried animal starts from a different state from an active, hydrated one. Space also brings ultraviolet and ionising radiation as well as temperature extremes. Separate groups and controls help identify which hazard caused which effect. Surviving a short orbital experiment is not the same as living on Mars for generations.'],
      ['Why it matters','Understanding cell drying and DNA repair helps scientists investigate life’s limits. The result is relevant to astrobiology, but it does not prove life travels between planets. Such a journey would require launch, a long trip, arrival, recovery and reproduction. Demonstrating one step does not establish them all.'],
      ['The next questions','Future studies can compare species, exposure times, radiation and the long-term health of survivors. Reproduction and Earth-based control groups matter as much as short-term movement after rehydration. Resilience is a measurable ability with limits, not indestructibility. The real biology is more interesting than the myth.']
    ])}
  }}),
feature({id:'blood-falls',category:'ecology',rubrics:['facts'],read:9,tags:['geografija','biologija'],
  hero:['blood-falls-portrait.jpg',L('Crveni trag Slapova krvi na glečeru Tejlor.','Rdeča sled Krvavih slapov na ledeniku Taylor.','The red outflow of Blood Falls on Taylor Glacier.'),L('„Slapovi krvi” na Antarktiku: boja potiče od slane vode bogate gvožđem.','»Krvavi slapovi« na Antarktiki: barvo povzroča z železom bogata slanica.','Antarctica’s Blood Falls: iron-rich brine makes the striking colour.')],
  images:[['blood-falls-detail.jpg',L('Detalj crvenog toka na antarktičkom ledu.','Podrobnost rdečega toka na antarktičnem ledu.','Closer view of the red flow on Antarctic ice.'),L('Na površini se sastojci slane vode susreću sa vazduhom i nastaje crvenkasta naslaga.','Na površju se sestavine slanice srečajo z zrakom in nastane rdečkasta sled.','At the surface the brine meets air and leaves a reddish deposit.')],['blood-falls-glacier.jpg',L('Glečer Tejlor u Antarktiku.','Ledenik Taylor na Antarktiki.','Taylor Glacier in Antarctica.'),L('Izvor slane vode nalazi se unutar i ispod ledenog sistema, a ne u „krvi” glečera.','Izvor slanice je v ledenem sistemu in pod njim, ne v »krvi« ledenika.','The brine comes from within and below the glacier, not from glacier “blood”.')]],
  source:[['US National Science Foundation — Science on the Ice','https://www.nsf.gov/geo/opp/documents/NSF%20Science%20on%20the%20Ice_fifth_edition.pdf'],['NSF public research archive — Blood Falls','https://par.nsf.gov/servlets/purl/10163057']],
  translations:{
    sr:{slug:'zasto-antarktik-ima-crvene-slapove-krvi',title:'Zašto iz antarktičkog leda izlaze crveni „Slapovi krvi”?',lead:'Ispod glečera Tejlor krije se slana voda sa gvožđem i mikroorganizmima; crvena boja otkriva hemiju, ne krv.',remember:'Slapovi krvi su crvenkasti iscedak slane vode na kraju glečera Tejlor na Antarktiku. Voda potiče iz izolovanog sistema ispod i unutar leda i sadrži rastvoreno gvožđe. Kada dođe na površinu i reaguje sa kiseonikom, ostavlja crvenkaste naslage bogate gvožđem. U slanoj vodi žive mikroorganizmi, ali uzrok boje nije životinjska krv.',term:'Slanica — voda sa visokim sadržajem rastvorenih soli.',sections:S([
      ['Crvena mrlja u beloj dolini','Na kraju glečera Tejlor, u antarktičkim Suvim dolinama, kroz led povremeno izlazi crvenkasta tečnost. Iz daljine deluje kao da led krvari, po čemu je mesto dobilo ime Blood Falls. To nije neprekidan veliki vodopad i svakako nije krv. U pitanju je slana voda koja izlazi iz pukotina i boji okolni led. Ekstremno hladna, suva oblast dodatno pojačava kontrast.','Samo gledanje fotografije ne otkriva izvor boje. Crvena može nastati od algi, minerala ili drugih procesa. Naučnici zato uzimaju uzorke, mere salinitet i hemijski sastav te koriste geofizičke metode da istraže put vode ispod glečera. U nauci upečatljiva slika počinje pitanje, a ne završava objašnjenje.'],
      ['Kako tečna voda ostaje pod ledom?','Voda ispod glečera bogata je solima. Soli snižavaju temperaturu na kojoj se tečnost smrzava, pa slanica može ostati tečna pri uslovima u kojima bi se čista voda zaledila. Pritisak leda i kretanje glečera takođe utiču na putanje kroz pukotine. Geofizička merenja ukazuju da izvor slanice leži kilometrima unutar sistema glečera Tejlor. Tačna dinamika iznenadnih izlivanja još se istražuje.','Važno je razlikovati slanu vodu ispod leda od morske vode koja sada slobodno teče do mesta. Soli mogu čuvati tragove mnogo starijeg morskog okruženja. Tokom duge geološke istorije doline i led su se menjali, pa se danas ispod glečera nalazi izolovan hemijski svet. Razumevanje tog sveta zahteva i geologiju i hemiju.'],
      ['Od gvožđa do crvene naslage','Slanica sadrži rastvoreno gvožđe koje u uslovima sa malo slobodnog kiseonika može ostati u drugačijem hemijskom obliku. Kada tečnost izađe i susretne vazduh, gvožđe se oksiduje i nastaju sitne čestice i minerali koji daju crvenkasto-smeđu boju. To je srodno rđanju, mada mineralna mešavina nije nužno jednaka rđi na biciklu. Boju ne treba objašnjavati jednom jednostavnom rečenicom bez hemijskih merenja.','Mikroskopi, analize rastvorenih jona i istraživanja mineralnih čestica dopunjuju se. Fotografija beleži posledicu, a laboratorija pomaže da razumemo reakcije koje su je stvorile. Kako voda izbija u različitim uslovima, izgled naslage može varirati. Krvavo ime je metafora, ne hemijski opis.'],
      ['Mikroorganizmi bez sunčeve svetlosti','U izolovanoj, hladnoj i slanoj vodi pronađeni su mikroorganizmi. Oni ne mogu računati na direktnu Sunčevu svetlost kao biljke na površini. Koriste hemijsku energiju i dostupne materije u vodi i steni, a njihova aktivnost može uticati na ciklus gvožđa i sumpora. Rastu sporo i žive u uslovima koji su za mnoge druge organizme nepovoljni.','To ne znači da su „besmrtni” ili da je njihov svet potpuno odvojen od svake promene. Naučnici ispituju kada je sistem nastao, koliko se materijal razmenjuje i kako se zajednica menja kada slanica izađe na površinu. Različiti uzorci daju delove odgovora. Jedna mala crvena mrlja tako postaje prirodna laboratorija za biologiju bez svetlosti.'],
      ['Zašto ovo zanima istraživače drugih svetova?','Na Marsu i ledenim satelitima mogu postojati hladne slane sredine ispod površine. Slapovi krvi pokazuju da tečna voda i mikroorganizmi mogu opstajati u nekim ledenim i mračnim uslovima na Zemlji. Poređenje pomaže da osmislimo instrumente koji traže hemijske tragove života i da prepoznamo moguće lažne signale. Ipak, zemaljski primer nije dokaz života na Marsu ili Evropi.','Najbolji zaključak je skromniji i jači: ako znamo kako se povezuju led, so, gvožđe i mikrobi, imamo bolji plan šta meriti negde drugde. Uzorkovanje mora biti pažljivo da se ne unese spoljašnji materijal i ne zameni lokalni signal kontaminacijom. Antarktički izvor je zbog toga vredan i za pitanja o čuvanju čistih uzoraka.'],
      ['Šta još ne znamo?','Nije do kraja jasno šta tačno pokreće svako izbijanje slanice na površinu, niti kako se svi njeni podzemni kanali menjaju kroz vreme. Istraživači kombinuju radar, hemiju, mikrobiologiju i posmatranje kretanja leda. Novi nalaz može promeniti detalje modela bez rušenja osnovne činjenice da je reč o slanoj vodi sa gvožđem.','Slapovi krvi su odličan primer za pitanje „verovali ili ne” upravo zato što stvarno objašnjenje nije manje zanimljivo od senzacionalnog naziva. Priča uključuje istoriju Antarktika, neobičnu hemiju i život u tami. Umesto da se zadovoljimo crvenom fotografijom, možemo pitati šta meri svaka metoda i koji deo slagalice još nedostaje.']
    ])},
    sl:{slug:'zakaj-iz-antarkticnega-leda-tece-rdeca-voda',title:'Zakaj iz antarktičnega ledu tečejo rdeči »Krvavi slapovi«?',lead:'Pod ledenikom Taylor je slana voda z železom in mikroorganizmi; rdeča barva govori o kemiji, ne o krvi.',remember:'Krvavi slapovi so rdečkasta slanica na koncu ledenika Taylor na Antarktiki. Voda prihaja iz izoliranega sistema v ledu in pod njim ter vsebuje raztopljeno železo. Ob stiku z zrakom nastajajo rdečkaste, z železom bogate usedline. V vodi živijo mikroorganizmi, vendar barva ni živalska kri.',term:'Slanica — voda z zelo veliko raztopljenih soli.',sections:S([
      ['Rdeča sled v beli dolini','Na robu ledenika Taylor v antarktičnih Suhih dolinah občasno priteče rdečkasta tekočina. Od daleč je videti, kot da led krvavi. Ne gre za kri ali velik stalen slap, temveč za slano vodo, ki prodira iz razpok. Fotografija sama ne pove, ali so vzrok alge, minerali ali drugačen proces. Zato raziskovalci jemljejo vzorce in merijo kemijsko sestavo.'],
      ['Kako voda ostane tekoča?','Raztopljene soli znižajo ledišče, zato lahko slanica ostane tekoča, ko bi čista voda že zmrznila. Tlak in gibanje ledu vplivata na kanale, po katerih izteka. Geofizikalne meritve kažejo izvor globlje v sistemu ledenika Taylor. Soli hranijo sledi starejšega morskega okolja, ne pomenijo pa, da danes tu prosto teče morska voda. Natančni sprožilci posameznih izlivov še niso dokončno pojasnjeni.'],
      ['Železo in rdeča barva','V slanici je raztopljeno železo. Ob stiku s kisikom na površju nastanejo drobni železovi delci in minerali rdečkasto-rjave barve. Proces je soroden rjavenju, vendar sestava ni nujno enaka rji na kovinskem predmetu. Laboratorijske analize ionov in mineralov dopolnjujejo terensko fotografijo. »Krvavi« je slikovito ime, ne kemijska diagnoza.'],
      ['Življenje v temi','Pod ledom živijo mikroorganizmi brez neposredne sončne svetlobe. Energijo dobivajo iz kemičnih reakcij in razpoložljivih snovi v vodi ter kamninah. Lahko vplivajo na kroženje železa in žvepla ter rastejo zelo počasi. Znanstveniki preučujejo njihovo raznolikost in povezavo s preteklim okoljem. Majhna rdeča sled tako odpre velika vprašanja biologije.'],
      ['Povezava z drugimi svetovi','Na Marsu in ledenih lunah bi lahko obstajale hladne, slane razmere pod površjem. Zemeljski primer pomaga načrtovati meritve kemijskih sledi. Ne dokazuje pa, da je življenje prisotno na teh svetovih. Pomembno je tudi preprečiti onesnaženje vzorcev, saj bi lahko tuje snovi ustvarile napačen signal.'],
      ['Kaj še ni jasno?','Natančna pot vseh podledeniških kanalov in sprožilci izlivov ostajajo predmet raziskav. Radar, kemija, mikrobiologija in opazovanje gibanja ledu dajejo različne dele odgovora. Novi podatki lahko popravijo podrobnosti, ne da bi spremenili osnovno ugotovitev: barvo povzroča železom bogata slanica. Resnična razlaga je zanimivejša od njenega strašljivega imena.']
    ])},
    en:{slug:'why-antarctica-has-red-blood-falls',title:'Why does red “Blood Falls” flow from Antarctic ice?',lead:'Iron-rich brine and microbes beneath Taylor Glacier explain the colour; no blood is involved.',remember:'Blood Falls is a reddish brine outflow at the end of Taylor Glacier in Antarctica. The water comes from an isolated system within and beneath ice and contains dissolved iron. On reaching the surface, iron-rich reddish deposits form. Microorganisms live in the brine, but animal blood is not the source of its colour.',term:'Brine — water with a high concentration of dissolved salts.',sections:S([
      ['A red mark in a white valley','A reddish liquid sometimes emerges at the end of Taylor Glacier in Antarctica’s Dry Valleys. From a distance the ice seems to bleed. It is neither blood nor a continuously roaring waterfall, but salty water escaping through ice. A picture alone cannot distinguish algae, minerals and other possible colour sources. Scientists sample the water and measure its chemistry to find out.'],
      ['How can water remain liquid?','Dissolved salts lower the freezing point. Brine can therefore stay liquid in conditions where pure water would freeze. Pressure and glacier movement affect the routes it takes through cracks. Geophysical measurements point to a source further inside the Taylor Glacier system. The salts preserve signs of an older marine environment; they do not mean seawater simply flows in from today’s coast. What triggers each release is still studied.'],
      ['Iron makes the colour','The brine carries dissolved iron. When it reaches air, iron-rich particles and minerals produce a red-brown stain. The chemistry resembles rusting, although the deposit is not necessarily identical to rust on a bicycle. Analyses of ions and mineral particles complement field photographs. “Blood” is a metaphor, not a chemical description.'],
      ['Life without sunlight','Microorganisms inhabit the cold, dark, salty system. They rely on chemical energy and materials in water and rock rather than direct sunlight. Their activity can affect cycles of iron and sulphur, and they grow slowly. Researchers study their diversity and how their community has changed through isolation. A small red stain becomes a natural laboratory for life in darkness.'],
      ['Why astrobiologists care','Mars and icy moons may contain cold, salty environments beneath their surfaces. Blood Falls helps scientists plan which chemical signals to measure and which misleading signals to exclude. It does not prove that life exists elsewhere. Clean sampling matters: contamination could be mistaken for a local sign of life.'],
      ['What remains unknown','The exact network of channels and the triggers for individual flows are still under investigation. Radar, chemistry, microbiology and studies of moving ice offer different pieces of the answer. New findings can revise details without changing the basic iron-rich-brine explanation. The real story is more intriguing than the dramatic name.']
    ])}
  }}),
feature({id:'axolotl-regeneration',category:'life',rubrics:['facts'],read:9,tags:['biologija','regeneracija'],
  hero:['axolotl-portrait.jpg',L('Aksolotl prirodne, tamne boje.','Aksolotl naravne temne barve.','Wild-type axolotl.'),L('Aksolotl je vodozemac poznat po obnavljanju delova tela.','Aksolotl je dvoživka, znana po obnovi delov telesa.','The axolotl is an amphibian famous for regrowing body parts.')],
  images:[['axolotl-healing.png',L('Naučni prikaz zarastanja kože aksolotla.','Znanstveni prikaz celjenja kože aksolotla.','Research illustration of axolotl skin healing.'),L('Istraživači proučavaju ćelijske procese tokom zarastanja, ne samo konačan izgled uda.','Raziskovalci preučujejo celične korake celjenja, ne le končnega videza uda.','Researchers examine the cellular steps of repair, not only the final shape.')],['axolotl-historic.jpg',L('Istorijska ilustracija aksolotla.','Zgodovinska ilustracija aksolotla.','Historical illustration of an axolotl.'),L('Ova neobična životinja privlačila je pažnju prirodnjaka mnogo pre moderne genetike.','Nenavadna žival je zanimala naravoslovce že pred sodobno genetiko.','Naturalists studied this remarkable animal long before modern genetics.')]],
  source:[['Natural History Museum — axolotl','https://www.nhm.ac.uk/discover/axolotls-amphibians-that-never-grow-up.html'],['Research review — limb regeneration','https://pmc.ncbi.nlm.nih.gov/articles/PMC5534018/']],
  translations:{
    sr:{slug:'kako-aksolotl-obnavlja-udove',title:'Aksolotl može ponovo da izraste nogu — kako to radi?',lead:'Obnavljanje uda zahteva precizno organizovane ćelije, nerve i signale; još ne znači da ljudi uskoro mogu isto.',remember:'Aksolotl je vodozemac koji može da obnovi izgubljeni ud kroz niz ćelijskih koraka. Rana se zatvara, a zatim nastaje blastema, skup ćelija iz kojih se gradi novo tkivo. Mišići, kosti, krvni sudovi i nervi moraju se ponovo složiti na odgovarajuća mesta. Razumevanje tog procesa može pomoći medicini, ali danas ne umemo da prenesemo potpunu regeneraciju udova na ljude.',term:'Blastema — masa aktivnih ćelija na mestu povrede iz koje tokom regeneracije nastaju nova tkiva.',sections:S([
      ['Životinja koja ostaje „mlada”','Aksolotl živi prirodno u vodenom okruženju oko Meksiko Sitija. Za razliku od mnogih drugih vodozemaca, uglavnom zadržava larvene osobine, uključujući spoljašnje škrge, i kada postane polno zreo. Ta pojava zove se neotenija. Nije isto što i besmrtnost ili život bez starenja. Njegov neobičan izgled privlači pažnju, ali za biologe je posebno važna sposobnost da posle povrede obnovi složene delove tela.','U prirodi je aksolotl kritično ugrožen. Istraživačke i kućne populacije ne znače da je vrsta bezbedna u izvornom staništu. Zagađenje, gubitak staništa i uvedene vrste ugrožavaju divlje životinje. Zato priča o regeneraciji mora uključiti i očuvanje živog sveta koji je omogućio istraživanje.'],
      ['Prvi korak: zatvaranje rane','Posle gubitka uda, ćelije kože brzo prekrivaju mesto povrede. Nastaje poseban pokrivač, rana epidermis, koji nije samo zavoj. On šalje i prima signale od tkiva ispod sebe. Istovremeno se menja ponašanje ćelija u ostatku uda; neke ponovo ulaze u ciklus deobe, a druge daju potomke koji će učestvovati u obnovi. Nije tačno da aksolotl ima jednu čudesnu univerzalnu ćeliju koja sama stvara sve.','Nervi su naročito važni u ranom delu procesa. U eksperimentima prekid nervnih veza može sprečiti normalno formiranje novog uda. To istraživačima govori da tkivo ne reaguje samo na povredu, već i na signale iz ostatka tela. Koža, nervi, vezivno tkivo i imunološke ćelije moraju uskladiti svoje odgovore.'],
      ['Blastema: gradilište novog uda','Ispod ranog pokrivača stvara se blastema, izbočina ispunjena aktivnim ćelijama. Ona raste, ali rast nije proizvoljan. Ćelije moraju „znati” gde se nalaze duž uda: da li pripadaju delu blizu tela ili prstima, prednjoj ili zadnjoj strani. Molekularni signali usmeravaju te odluke. Postepeno nastaju kost, mišić, koža, krvni sudovi i nervi u funkcionalnom rasporedu.','Pitanje odakle tačno dolaze sve ćelije dugo se istražuje. U različitim tkivima važni mogu biti postojeće matične ćelije i ćelije koje menjaju svoje stanje. Nije opravdano reći da se svaka ćelija potpuno vraća u embrionalno stanje. Savremene metode obeležavanja ćelija i analize gena omogućavaju da se prati njihov put tokom obnove.'],
      ['Obnoviti oblik nije dovoljno','Novi ud mora da bude povezan sa nervnim sistemom i krvotokom i da radi. Laboratorijski snimci prate pojavu prstiju, zglobova i mišića kroz vreme. Ista životinja ne regeneriše uvek jednako brzo: uslovi, starost i mesto povrede utiču na proces. U nekim eksperimentima veća oštećenja zglobova ili drugačija vrsta povrede ne popravljaju se savršeno. Zato je popularni opis „ponovo izraste šta god poželi” netačan.','Aksolotl može obnoviti i neka druga tkiva, što ga čini izuzetno korisnim modelom. Ali istraživači razlikuju obnovu pojedinog tkiva od ponovne izgradnje složenog organa. Za svaku tvrdnju treba navesti šta je uklonjeno, koliko je obnovljeno i kako je funkcija proverena. Slika novog uda sama nije dovoljna za zaključak.'],
      ['Zašto to ljudi ne rade isto?','Ljudsko telo odlično zarasta mnoge rane, ali kod gubitka velikog uda obično stvara ožiljak umesto blasteme koja ponovo gradi čitav obrazac. Naš imunološki odgovor, ćelijski signali, razvojna istorija i veličina tela razlikuju se od aksolotlovih. Ne postoji jedan „gen za regeneraciju” koji bismo jednostavno uključili. Potrebno je razumeti kako se mnogi sistemi međusobno usklađuju, a zatim proveriti bezbednost svakog pokušaja promene.','Regenerativna medicina već razvija metode za pojedina tkiva, ali celokupna ljudska ruka ili noga je mnogo teži cilj. Nekontrolisano podsticanje rasta ćelija moglo bi imati ozbiljne posledice. Učenje od aksolotla zato znači pažljivo istraživanje, ne najavu brzog čudotvornog leka.'],
      ['Kako istraživači traže odgovor','Naučnici porede zdrava, povređena i obnovljena tkiva, prate koje ćelije izražavaju koje gene i proveravaju šta se dogodi kada blokiraju određeni signal. Zatim pokušavaju da isti nalaz ponove u drugim životinjama i modelima. Važno je da se rezultat iz jedne laboratorije potvrdi nezavisno, jer se uslovi uzgoja i uzrast životinja razlikuju. Složena regeneracija je sistemski proces koji traži mnogo vrsta podataka.','Aksolotl nam tako pruža dve lekcije: priroda poznaje rešenja koja ljudsko telo uglavnom ne koristi, a put od razumevanja do medicinske primene je dug. Ako očuvamo vrstu i njeno stanište, čuvamo i mogućnost da još mnogo naučimo iz tog neobičnog vodozemca.']
    ])},
    sl:{slug:'kako-aksolotl-obnovi-okončino',title:'Aksolotlu lahko znova zraste noga — kako?',lead:'Obnova okončine zahteva usklajene celice, živce in signale; ljudje tega še ne znamo ponoviti.',remember:'Aksolotl lahko obnovi izgubljeno okončino po več zaporednih celičnih korakih. Rana se zapre, nato nastane blastema, skupek celic za nova tkiva. Mišice, kosti, žile in živci se morajo ponovno razporediti na prava mesta. Razumevanje lahko pomaga medicini, vendar popolne obnove človeške roke ali noge še ne znamo omogočiti.',term:'Blastema — skupek aktivnih celic na mestu poškodbe, iz katerega med regeneracijo nastajajo tkiva.',sections:S([
      ['Dvoživka, ki ohrani mladostne lastnosti','Aksolotl izvira iz vodnega okolja okoli Ciudad de Méxica. Tudi spolno zrel večinoma obdrži zunanje škrge in druge larvalne značilnosti; pojav imenujemo neotenija. To ni nesmrtnost. V naravi je kritično ogrožen zaradi izgube in onesnaženja življenjskega prostora ter tujerodnih vrst. Raziskovalne populacije ne nadomestijo divjih.'],
      ['Rana se najprej zapre','Po izgubi uda kožne celice hitro prekrijejo rano in ustvarijo poseben pokrov. Ta pošilja signale tkivom pod seboj. Nekatere celice se znova delijo, druge prispevajo potomke. Pomembni so tudi živci: prekinitev živčnih signalov lahko zavre zgodnjo obnovo. Ne gre za eno čudežno celico, ki bi sama ustvarila vse.'],
      ['Blastema kot gradbišče','Pod pokrovom nastane blastema. Celice rastejo, vendar morajo vedeti, kje so vzdolž okončine, da oblikujejo pravi del. Molekularni signali usmerjajo nastanek kosti, mišic, kože, žil in živcev. Različna tkiva prispevajo različne vrste celic; ni dokazano, da se vse povsem vrnejo v embrionalno stanje. Sledilne metode danes omogočajo preverjanje njihovega izvora.'],
      ['Oblika in delovanje','Nova okončina mora biti povezana z živci in krvnim obtokom ter uporabna. Hitrost in popolnost obnove sta odvisni od starosti, okolja in vrste poškodbe. Nekatere večje poškodbe sklepov se tudi pri aksolotlu ne popravijo popolnoma. Slika novega uda zato ni dovolj: raziskovalci merijo strukturo in funkcijo.'],
      ['Zakaj človek ne zmore enako?','Ljudje zacelimo mnoge rane, pri izgubi velike okončine pa običajno nastane brazgotina. Naši imunski odzivi in celični signali se razlikujejo. Ni enega samega »gena za regeneracijo«, ki bi ga lahko preprosto vključili. Spodbujanje rasti mora biti varno in nadzorovano. Posamezni uspehi regenerativne medicine še ne pomenijo obnove cele roke.'],
      ['Kaj raziskujemo naprej','Znanstveniki primerjajo zdrava in poškodovana tkiva, sledijo izražanju genov ter preverjajo učinek posameznih signalov. Rezultate morajo ponoviti drugi laboratoriji. Razumevanje naravnega procesa je prvi korak, prenos v medicino pa veliko daljši. Varovanje divjih aksolotlov ohranja tudi pomemben vir znanja.']
    ])},
    en:{slug:'how-axolotls-regrow-limbs',title:'An axolotl can regrow a leg — how does it work?',lead:'Regrowing a limb demands coordinated cells, nerves and signals; humans cannot yet do the same.',remember:'An axolotl can rebuild a lost limb through a sequence of cellular steps. Skin closes the wound, then a blastema forms to generate new tissues. Muscles, bones, vessels and nerves must be organised into the right places. Understanding this may help medicine, but we cannot yet regrow a complete human arm or leg.',term:'Blastema — a mass of active cells at an injury site from which regenerating tissues develop.',sections:S([
      ['An amphibian that keeps juvenile traits','The axolotl lives in aquatic habitats around Mexico City. Even as a breeding adult it usually retains external gills and other larval features, a condition called neoteny. That is not immortality. Wild axolotls are critically endangered by habitat loss, pollution and introduced species. Animals in laboratories and homes do not make the wild population secure.'],
      ['The wound closes first','After limb loss, skin cells rapidly cover the injury and form a specialised wound layer. It sends signals to underlying tissue. Some cells re-enter the division cycle; others produce descendants for reconstruction. Nerves are important early on: removing their influence can prevent normal regrowth. There is no single magic cell that creates everything by itself.'],
      ['The blastema is a building site','A blastema forms beneath the wound covering. Its cells proliferate but must also respond to positional information so the correct structures appear in the correct places. Signals coordinate bone, muscle, skin, vessels and nerves. Different tissues may contribute different progenitors; not every cell simply resets to an embryonic state. Cell tracing allows researchers to test where new tissue comes from.'],
      ['Shape is not enough','A new limb must reconnect with nerves and blood supply and actually function. The speed and completeness of regeneration depend on age, environment and injury type. Some large joint injuries do not repair perfectly even in axolotls. A photograph of a new limb is therefore only part of the evidence. Scientists also test anatomy and use.'],
      ['Why humans differ','Humans heal many wounds, but after losing a large limb we usually form a scar instead of a whole-limb blastema. Immune responses and cell signals differ. There is no single regeneration switch to turn on. Stimulating growth would need careful control and safety checks. Current regenerative medicine can help some tissues, but recreating an entire arm is a far harder goal.'],
      ['The next experiments','Researchers compare intact and injured tissue, track gene expression and test what happens when signals are blocked. Independent laboratories need to reproduce promising results. Learning from axolotls is valuable, but moving from understanding to treatment is a long process. Protecting the wild species also preserves a remarkable source of knowledge.']
    ])}
  }}),
feature({id:'venus-long-day',category:'space',rubrics:['facts'],read:8,tags:['astronomija','Venera'],
  hero:['venus-portrait.jpg',L('Venera prikazana na osnovu NASA podataka.','Venera na podlagi podatkov Nase.','Venus shown with NASA data.'),L('Venera se veoma sporo okreće oko ose, u smeru suprotnom od većine planeta.','Venera se okoli osi vrti zelo počasi in v obratni smeri od večine planetov.','Venus rotates very slowly and opposite to most planets.')],
  images:[['venus-views.jpg',L('Stvarni i pojačani prikaz oblaka Venere.','Resnični in poudarjeni pogled na Venerine oblake.','Natural and enhanced views of Venus’s clouds.'),L('Gusta atmosfera skriva površinu, pa su za njeno proučavanje važni radari i sonde.','Gosto ozračje skriva površje; zato so pomembni radarji in sonde.','Thick clouds hide the surface, making radar and probes important.')],['venus-magellan.png',L('Umetnička predstava sonde Magelan kod Venere.','Umetniška upodobitev sonde Magellan pri Veneri.','Artist’s depiction of Magellan at Venus.'),L('Magelan je radarom kartirao veliki deo Venerine površine.','Magellan je z radarjem kartiral velik del Venerinega površja.','Magellan used radar to map much of Venus’s surface.')]],
  source:[['NASA Science — Venus facts','https://science.nasa.gov/venus/venus-facts/'],['NASA JPL — Venus and Magellan','https://science.nasa.gov/mission/magellan/']],
  translations:{
    sr:{slug:'dan-na-veneri-duzi-od-godine-ali-koji-dan',title:'Na Veneri dan traje duže od godine — ali koji dan?',lead:'Jedan obrt Venere traje oko 243 zemaljska dana, a njen obilazak Sunca 225; izlazak Sunca je sasvim druga računica.',remember:'Venera se oko ose okrene za približno 243 zemaljska dana, a oko Sunca obiđe za oko 225. Zbog toga je njen zvezdani dan duži od godine. Ipak, vreme između dva izlaska Sunca traje približno 117 zemaljskih dana. Razlika nastaje zato što se Venera okreće vrlo sporo i u suprotnom smeru od većine planeta.',term:'Zvezdani dan — vreme jednog obrtaja planete u odnosu na udaljene zvezde; Sunčev dan meri vreme između dva podneva.',sections:S([
      ['Šta zapravo poredimo?','Na Zemlji smo navikli da reč „dan” gotovo uvek znači 24 časa, a „godina” jedan obilazak Sunca. U astronomiji postoji važna razlika. Zvezdani dan je vreme jednog obrtaja planete u odnosu na daleke zvezde; Sunčev dan meri ciklus Sunca na nebu, na primer od jednog izlaska do sledećeg. Venera se oko ose obrne približno jednom u 243 zemaljska dana. Sunce obiđe približno jednom u 225 zemaljskih dana. Tako njen zvezdani dan zaista traje duže od godine.','Ako bismo rekli samo „dan”, čitalac bi prirodno zamislio ciklus svetlosti i tame. Na Veneri taj ciklus ne traje 243 dana. U astronomiji precizne definicije nisu sitničavost nego način da ista rečenica ne prenese pogrešnu sliku.'],
      ['Zašto Sunce izlazi na „pogrešnoj” strani?','Venera se okreće retrogradno: posmatrano iznad severne strane Sunčevog sistema, smer njenog okretanja suprotan je smeru u kome većina planeta rotira. Zbog toga bi Sunce, kada bi ga oblaci pustili da se lepo vidi sa tla, izlazilo na zapadu i zalazilo na istoku. Sporo okretanje i obilazak oko Sunca zajedno određuju koliko treba da Sunce opet zauzme isti položaj na nebu. Rezultat je Sunčev dan od oko 117 zemaljskih dana.','To je kraće od Venerine godine, iako je zvezdani dan duži. Nema protivrečnosti: merimo dva različita povratka, jedan u odnosu na zvezde, drugi u odnosu na Sunce koje se prividno pomera jer planeta kruži oko njega. Slična razlika postoji i na Zemlji, samo je mala: zvezdani dan je nekoliko minuta kraći od 24 časa.'],
      ['Kako su astronomi izmerili rotaciju?','Gusta Venerina atmosfera prekriva površinu oblacima, pa teleskop u vidljivoj svetlosti ne može pratiti planinu kao oznaku okretanja. Radar može proći kroz oblake i mapirati neravnine na tlu. Zemaljski radari i svemirske sonde upoređivali su položaje površinskih detalja kroz vreme. Misija Magelan u devedesetim godinama prošlog veka mapirala je veliki deo planete i pružila detalje o vulkanskim ravnicama, kraterima i reljefu.','Nije dovoljno pratiti samo oblake: oni kruže oko Venere mnogo brže od čvrste površine. Kada u vestima čujemo da atmosfera „obiđe planetu za nekoliko dana”, to ne znači da se i stenovita planeta okreće tim tempom. Razlikujemo rotaciju tla, cirkulaciju vazduha i orbitalno kretanje.'],
      ['Svet koji nije sličan Zemlji','Venera je približno Zemljine veličine, ali njena površina je izuzetno vrela zbog gustog omotača ugljen-dioksida i snažnog efekta staklene bašte. Pritisak pri tlu približno je devedeset puta veći nego kod nas. Oblaci sadrže kapljice sumporne kiseline. Zato zamisao o posmatraču koji stoji na tlu i čeka izlazak Sunca ostaje misaoni eksperiment, ne turistički plan.','Malo naginjanje ose znači da nema sezona nalik našim uobičajenim sezonskim razlikama. Iz tih činjenica ne treba zaključiti da je Venera „mrtva” u geološkom smislu; svemirske misije i dalje istražuju znake vulkanske aktivnosti i promene površine. Njena atmosfera je i važan primer koliko različite mogu biti planete slične veličine.'],
      ['Zašto je ova zanimljivost korisna?','Razlikovanje zvezdanog i Sunčevog dana pomaže nam da razumemo i Merkur, Mesec i planete oko drugih zvezda. Planeta može biti gravitaciono vezana tako da isto lice stalno gleda ka svojoj zvezdi, ili može imati neobične odnose rotacije i orbite. Odatle slede različiti obrasci osvetljenja i temperature, ali atmosfera može prenositi toplotu i menjati ih.','Najbolja verzija popularne tvrdnje glasi: „Venerin obrt u odnosu na zvezde traje duže od njenog obilaska oko Sunca.” Zvuči manje dramatično, ali otvara bolje pitanje — zašto postoje dva načina da izmerimo dan?']
    ])},
    sl:{slug:'dan-na-veneri-je-daljsi-od-leta',title:'Dan na Veneri je daljši od leta — toda kateri dan?',lead:'En obrat traja približno 243 zemeljskih dni, obhod Sonca 225, cikel sončnih vzhodov pa nekaj drugega.',remember:'Venera se okoli osi obrne v približno 243 zemeljskih dneh, okoli Sonca pa v približno 225. Njen zvezdni dan je zato daljši od leta. Čas med dvema sončnima vzhodoma pa meri približno 117 zemeljskih dni. Razliko povzroča počasno vrtenje v smeri, nasprotni večini planetov.',term:'Zvezdni dan — čas obrata glede na oddaljene zvezde; sončni dan meri povratek Sonca na isti položaj na nebu.',sections:S([
      ['Kaj primerjamo?','V vsakdanjem življenju dan pomeni 24 ur, v astronomiji pa ločimo dva pomena. Zvezdni dan meri obrat glede na oddaljene zvezde. Sončni dan meri čas med dvema zaporednima poldnevoma ali vzhodoma Sonca. Venera za obrat potrebuje približno 243 zemeljskih dni, za obhod Sonca pa 225. Zato je njen zvezdni dan res daljši od leta, cikel svetlobe in teme pa ni enak temu času.'],
      ['Obrnjeno vrtenje','Venera se vrti v nasprotno smer od večine planetov. Sonce bi na njenem površju navidezno vzhajalo na zahodu in zahajalo na vzhodu. Obrat ter gibanje planeta okoli Sonca skupaj določata, kdaj je Sonce spet na istem mestu na nebu. Sončni dan traja približno 117 zemeljskih dni. Protislovja ni: zvezdni in sončni dan sta različni meritvi.'],
      ['Merjenje skozi oblake','Gosti oblaki skrivajo površje, zato opazovanje premikanja oblakov ne pove, kako hitro se vrti kamnita tla. Radar prodre skozi ozračje in omogoča spremljanje površinskih znamenj. Vesoljska sonda Magellan je v devetdesetih letih kartirala velik del Venere. Oblačna plast kroži mnogo hitreje od čvrstega planeta; teh dveh gibanj ne smemo zamenjati.'],
      ['Svet skrajnosti','Venera je približno Zemljine velikosti, toda njeno gosto ozračje iz ogljikovega dioksida ustvarja izjemno močan učinek tople grede. Površje je zelo vroče, tlak pa približno devetdesetkrat večji kot na Zemlji. Oblaki vsebujejo žveplovo kislino. Človek, ki čaka na sončni vzhod, je zato le miselni poskus. Planet raziskujemo z radarjem in sondami.'],
      ['Nauk natančnih besed','Podobno ločimo različne dneve na Merkurju, Zemlji in eksoplanetih. Hitrost vrtenja in obhoda skupaj določata vzorec osvetlitve, ozračje pa lahko prenaša toploto. Priljubljeno trditev najbolje izrečemo natančno: Venerin obrat glede na zvezde traja dlje od njenega leta. Tako zanimivost postane začetek razlage, ne zavajajoč slogan.']
    ])},
    en:{slug:'venus-day-longer-than-year-which-day',title:'A day on Venus lasts longer than a year — which day?',lead:'Venus rotates once in about 243 Earth days and orbits the Sun in 225; the sunrise cycle is another matter.',remember:'Venus rotates relative to the stars in roughly 243 Earth days and orbits the Sun in about 225. Its sidereal day is therefore longer than its year. Yet the interval between sunrises is about 117 Earth days. Slow rotation in the opposite direction from most planets explains the difference.',term:'Sidereal day — one rotation relative to distant stars; a solar day measures the Sun’s return to the same place in the sky.',sections:S([
      ['What are we comparing?','In daily life “day” means 24 hours. In astronomy, a sidereal day is one rotation relative to the distant stars, while a solar day is the time between two successive noons or sunrises. Venus takes about 243 Earth days to rotate and 225 to orbit the Sun. The first figure is indeed longer than its year, but it is not the cycle of daylight and darkness at one place. Precise definitions prevent a catchy fact from being misleading.'],
      ['Backward rotation','Venus rotates opposite to most planets. From the surface the Sun would appear to rise in the west and set in the east. Rotation and orbital motion together determine when the Sun returns to the same place in the sky. The solar day is about 117 Earth days. There is no contradiction: the sidereal and solar days measure different returns. Earth has the same distinction, although the difference is only a few minutes.'],
      ['Measuring through clouds','Thick clouds hide the surface, so watching the clouds does not tell us how fast the solid planet turns. Radar can reach surface features through the atmosphere. NASA’s Magellan mission mapped much of Venus in the 1990s, showing plains, craters and rugged features. Its atmosphere circulates much faster than the ground rotates. Confusing cloud motion with the planet’s rotation would give the wrong answer.'],
      ['A world unlike Earth','Venus is roughly Earth-sized but its dense carbon dioxide atmosphere produces an extreme greenhouse effect. The surface is very hot and the pressure is about ninety times Earth’s surface pressure. Clouds contain sulphuric acid droplets. A person waiting outside for sunrise is only a thought experiment. Probes and radar, not tourists, reveal this world.'],
      ['A lesson about definitions','Sidereal and solar days also matter on Mercury, the Moon and exoplanets. Spin and orbital motion together determine patterns of light, while an atmosphere can redistribute heat. The accurate headline is: Venus’s rotation relative to the stars takes longer than its orbit of the Sun. That careful wording opens a better scientific question than a slogan does.']
    ])}
  }}),
feature({id:'giant-fungus',category:'life',rubrics:['facts'],read:9,tags:['biologija','ekologija'],
  hero:['fungus-portrait.jpg',L('Plodna tela gljive Armillaria ostoyae.','Trosnjaki glive Armillaria ostoyae.','Fruiting bodies of Armillaria ostoyae.'),L('Pečurke su vidljiv deo gljive; veći deo organizma širi se kroz drvo i zemljište.','Gobe so vidni del glive; večji del se širi skozi les in tla.','Mushrooms are the visible part; most of the fungus spreads through wood and soil.')],
  images:[['fungus-forest.jpg',L('Gljive Armillaria ostoyae u šumskom staništu.','Glive Armillaria ostoyae v gozdu.','Armillaria ostoyae in forest habitat.'),L('Jedan podzemni genetski jedinstven organizam može obuhvatiti veliki deo šume.','En sam podzemni genetski enoten organizem lahko zajame velik del gozda.','One genetically distinct underground organism can span a large forest area.')],['fungus-mushrooms.jpg',L('Grupa plodnih tela gljive Armillaria.','Skupina trosnjakov glive Armillaria.','A cluster of Armillaria fruiting bodies.'),L('Vidljive pečurke ne pokazuju same gde se završava podzemna mreža.','Vidne gobe same ne pokažejo, kje se konča podzemna mreža.','Visible mushrooms alone cannot reveal the limits of the underground network.')]],
  source:[['US Forest Service — Humongous Fungus','https://www.fs.usda.gov/sites/nfs/files/r06/malheur/publication/Humongus%20Fungus.pdf'],['US Forest Service — Malheur National Forest','https://www.fs.usda.gov/r06/malheur']],
  translations:{
    sr:{slug:'najveca-gljiva-na-svetu-skrivena-u-sumi',title:'Najveća gljiva krije se pod šumom: kako znamo da je jedna?',lead:'U američkoj šumi Malheur jedan organizam roda Armillaria prostire se kroz ogromnu površinu; pečurke su samo mali vidljivi deo.',remember:'U šumi Malheur u Oregonu istraživači su identifikovali jednu genetski povezanu jedinku gljive Armillaria ostoyae na oko 2.385 jutara, približno 965 hektara. Većina organizma raste kao podzemna mreža niti i traka koje zahvataju korenje drveća. Vidljive pečurke su plodna tela, a ne cela gljiva. Procene starosti i mase imaju širok raspon jer se organizam ne može jednostavno izvaditi i izmeriti.',term:'Micelija — mreža gljivičnih niti koja čini veliki deo tela većine gljiva.',sections:S([
      ['Pečurke su vrh mnogo veće priče','Kada u šumi ugledamo grupu pečuraka, ne gledamo nužno čitav organizam. One su plodna tela koja stvaraju i rasipaju spore. Veći deo gljive čine tanke niti, hife, u drvetu i zemljištu. One se spajaju u miceliju i mogu da se šire daleko od mesta gde se pojavljuju pečurke. Kod vrste Armillaria ostoyae postoje i tamne vrpce zvane rizomorfe, koje izgledom podsećaju na vezice za cipele.','U Nacionalnoj šumi Malheur u Oregonu istraživači su proučavali velike zone u kojima je ova gljiva napadala korenje drveća. Rezultat nije jedna džinovska pečurka veličine grada. Reč je o razgranatom organizmu, uglavnom skrivenom, sa mnogo mesta na kojima može proizvesti plodna tela. To menja način na koji zamišljamo „veličinu” živog bića.'],
      ['Kako se utvrđuje da je to jedna jedinka?','Dve pečurke iste vrste ne moraju biti isti organizam. Da bi proverili kontinuitet, istraživači uzimaju uzorke sa različitih mesta, upoređuju genetske oznake i prate raspored zaraženih stabala i micelije. Ako udaljeni uzorci pripadaju istom klonu, zaključuju da se radi o jednoj genetskoj jedinki. Granice nisu uvek oštre kao zid: delovi mreže mogu biti fizički prekinuti, a ostati potomci istog organizma.','Zato su u izveštajima važni izrazi „genet”, „klon” i „centar bolesti korena”. Jedan genet nastaje iz iste prvobitne kombinacije gena i širi se rastom. Ne brojimo pečurke, već povezujemo uzorke. Genetika pretvara šumski mit u proverljivu tvrdnju, ali zahteva i pažljivo definisanje šta uopšte znači „jedan”.'],
      ['Koliko je velika?','Izveštaj američke Šumarske službe opisuje najveći identifikovani genet Armillaria ostoyae u Malheuru na 2.385 jutara, oko 965 hektara. To je površina mnogo veća od tipičnog gradskog parka. Ne znači da je svaki kvadratni centimetar zemlje ispunjen gustom gljivom; govori o rasponu prostora kroz koji je ista jedinka otkrivena. Njena biomasa procenjuje se posredno, na osnovu uzoraka i pretpostavki, pa se procene veoma razlikuju.','Starost se takođe ne meri brojanjem godova kao kod drveta. Naučnici koriste širinu kolonije i moguću brzinu širenja. Za isti genet u dokumentu se navode procene od približno 1.900 do 8.650 godina, zavisno od pretpostavljene brzine rasta. Senzacionalni naslov „stara tačno toliko godina” prikriva neizvesnost koja je ključni deo naučnog rezultata.'],
      ['Divovski organizam i šuma','Armillaria ostoyae nije neutralna mreža niti: može da parazitira na drveću i izaziva bolest korena. Zaraženo drvo slabije prenosi vodu i hranljive materije, a grupa stabala može odumirati. To stvara otvore u šumi, menja staništa i utiče na rad šumara. Gljiva se istovremeno uklapa u širi ekosistem kao razlagač organske materije. Njeno prisustvo nije prosto priča o „zloj” gljivi.','Šume se stalno menjaju zbog suše, požara, insekata, klimatskih uslova i mikroorganizama. Naučnici koji proučavaju korensku bolest moraju odvojiti uticaj gljive od drugih uzroka propadanja. Uzorkovanje na mnogo mesta i dugoročno praćenje daju bolju sliku nego jedna fotografija mrtvog stabla.'],
      ['Da li je to najveće živo biće?','Zavisi od merila. Jedan organizam može biti rekorder po površini, drugi po masi, treći po visini, a četvrti po dužini života. Razlikuje se i šta smatramo jednom jedinkom kod klonalnih biljaka i gljiva. Malheurska Armillaria često se opisuje kao najveći poznati organizam po procenjenoj biomasi, ali ta procena zavisi od modela i buduća otkrića mogu promeniti rang-listu.','Pošteniji zaključak je da pod nogama može postojati organizam koji obuhvata veliki deo šume, a čije granice otkrivamo genetikom. Njegova stvarna površina, masa i starost imaju različite nivoe pouzdanosti. To nije slabost priče nego prilika da naučimo kako se veliki, skriveni organizmi uopšte mere.'],
      ['Šta još možemo istraživati?','Istraživači mogu pratiti kako se genet širi kroz različita tla, koje vrste drveća zahvata i kako na njega utiču suša i temperatura. Bolje genomske metode pomažu da se odvoje bliski klonovi. Podzemni senzori i uzorkovanje korena daju podatke o aktivnosti koju pečurke na površini ne otkrivaju. Takva istraživanja su važna i za zaštitu šuma.','Najneobičnije možda nije sama brojka, nego pomeranje perspektive. Ono što vidimo kao nekoliko pečuraka može biti samo kratkotrajan znak procesa koji traje hiljadama godina. Šuma pod zemljom ima sopstvenu istoriju, a nauka je može otkrivati bez izmišljanja tačne mase ili starosti tamo gde je još nema.']
    ])},
    sl:{slug:'najvecja-gliva-skrita-pod-gozdom',title:'Največja gliva se skriva pod gozdom: kako vemo, da je ena?',lead:'V oregonskem gozdu Malheur ena gliva Armillaria prepreda ogromno območje; gobe so le vidni del.',remember:'V gozdu Malheur v Oregonu so raziskovalci odkrili genetsko povezano glivo Armillaria ostoyae na približno 2385 akrih oziroma 965 hektarih. Večina organizma raste kot podzemna mreža niti in pasov med koreninami dreves. Vidne gobe so trosnjaki, ne vsa gliva. Starost in maso ocenjujejo posredno, zato imajo številke široke razpone.',term:'Micelij — mreža glivnih niti, ki tvori velik del telesa večine gliv.',sections:S([
      ['Gobe niso vsa gliva','Gobe, ki jih vidimo v gozdu, so trosnjaki za razmnoževanje. Večji del glive sestavljajo tanke hife v lesu in prsti. Pri vrsti Armillaria ostoyae so pomembni tudi temni pasovi, rizomorfi. V narodnem gozdu Malheur v Oregonu gliva sega prek velikega območja. Ne gre za eno ogromno gobo nad tlemi, temveč za razvejano, večinoma skrito telo.'],
      ['Kako prepoznamo eno osebko?','Dve gobi iste vrste nista nujno del istega organizma. Znanstveniki jemljejo vzorce na več krajih, primerjajo genetske oznake ter sledijo razporedu okuženih dreves. Če imajo oddaljeni vzorci isti klonski izvor, govorijo o enem genetu. Njegovi deli so lahko fizično ločeni, a genetsko izvirajo iz istega organizma. Zato je treba pojem »ena gliva« natančno opredeliti.'],
      ['Površina, masa in starost','Poročilo ameriške gozdne službe največji poznani genet v Malheuru opisuje na 2385 akrih, približno 965 hektarih. To ne pomeni, da vsak centimeter tal zapolnjuje gosta gliva. Maso ocenjujejo iz vzorcev in modelov, ne s tehtanjem celotnega organizma. Starost izračunajo iz velikosti in predpostavljene hitrosti širjenja. Zato nastane širok razpon, od približno 1900 do 8650 let.'],
      ['Del gozdnega ekosistema','Armillaria ostoyae lahko napade korenine dreves in povzroči bolezen. Prizadeta drevesa težje sprejemajo vodo in hranila, nekatera odmrejo. Gliva sodeluje tudi pri razgradnji organskih snovi. Gozd spreminjajo še suša, požari, žuželke in drugi mikroorganizmi, zato ni vsaka mrtva smreka dokaz le ene bolezni. Raziskave morajo ločiti več vzrokov.'],
      ['Največji po katerem merilu?','Organizme lahko primerjamo po površini, biomasi, višini ali starosti. Klonske rastline in glive odpirajo tudi vprašanje, kaj šteje za eno osebko. Malheurska Armillaria je izjemna, a njena masa je ocena in prihodnja odkritja lahko spremenijo lestvico. Najbolj dragoceno spoznanje je, da genetika razkrije skritega gozdnega velikana, ki ga posamezna fotografija ne more pokazati.'],
      ['Kaj raziskujemo naprej','Raziskovalci spremljajo širjenje geneta, vrste dreves, sestavo tal in vpliv podnebja. Genomske metode pomagajo ločevati sorodne klone, vzorci korenin pa kažejo dejavnost pod površjem. Šele več vrst meritev pove, kako se velika gliva vključuje v spreminjajoči se gozd.']
    ])},
    en:{slug:'the-giant-fungus-hidden-under-a-forest',title:'A giant fungus hides beneath a forest: how do we know it is one?',lead:'In Oregon’s Malheur forest one Armillaria organism spans an immense area; mushrooms are only its visible signs.',remember:'Researchers identified a genetically connected Armillaria ostoyae fungus across roughly 2,385 acres, about 965 hectares, in Oregon’s Malheur forest. Much of it grows underground as threads and cordlike structures among tree roots. The mushrooms are fruiting bodies, not the whole fungus. Age and mass are indirect estimates with wide uncertainty because the organism cannot simply be lifted and weighed.',term:'Mycelium — the network of fungal threads forming much of the body of most fungi.',sections:S([
      ['Mushrooms are only the visible part','Mushrooms in a forest are fruiting bodies that release spores. Most of a fungus consists of fine hyphae in wood and soil. Armillaria ostoyae also produces dark cordlike rhizomorphs. In Oregon’s Malheur National Forest the fungus occupies a vast area. It is not one enormous above-ground mushroom but a branching, mostly hidden body. This changes what we picture when we hear “large organism”.'],
      ['How can it be one individual?','Two mushrooms of the same species need not belong to the same organism. Researchers sample different places, compare genetic markers and map affected trees. Samples with one clone’s genetic identity point to a single genet. Physical parts can sometimes be separated while still descending from the same original individual. “One fungus” therefore requires a careful biological definition, not a count of mushrooms.'],
      ['Area, weight and age','A US Forest Service report describes the largest Malheur genet across 2,385 acres, about 965 hectares. That does not mean dense fungal tissue fills every centimetre of soil. Mass is estimated from samples and assumptions, not from putting the entire organism on a scale. Age is inferred from its width and plausible growth rates. The resulting estimates range from roughly 1,900 to 8,650 years; a single exact birthday would be misleading.'],
      ['The forest around it','Armillaria ostoyae can infect tree roots and cause disease. Affected trees struggle to take up water and nutrients, and some die. The fungus also participates in decomposition. Forests are shaped by drought, fire, insects and other microorganisms too, so one dead tree does not prove one cause. Researchers need broad sampling and long-term monitoring to understand its role.'],
      ['Largest by what measure?','Living things can be ranked by area, mass, height or age. Clonal fungi and plants also challenge the meaning of an individual. The Malheur Armillaria is extraordinary, but its biomass is an estimate and later discoveries could change any record list. The strongest conclusion is that genetics reveals a forest-sized hidden organism that a surface photograph cannot show.'],
      ['What remains to study','Scientists can follow how the genet spreads through soils, which trees it reaches and how drought or temperature affect it. Better genomic methods separate nearby clones; root samples reveal activity underground. Many kinds of evidence are needed to understand a huge fungus within a changing ecosystem.']
    ])}
  }}),
];
